#!/usr/bin/env bash
# =============================================================================
# upload_to_r2.sh — Day 17 Phase-1 data sync to Cloudflare R2
# =============================================================================
# Generated by Claude on 2026-06-02 for Abi's CoT-Resampling Collusion Probes
# project. Uploads the verified-clean v4 batch, judge results, predictions, and
# framing memo to the R2 source-of-truth bucket set up on Day 1.
#
# RUN FROM: /workspace/narcbench/ on the active RunPod pod.
# REQUIRES: rclone (installed automatically if missing) and ~1 GB free disk.
#
# IMPORTANT — REVIEW BEFORE RUNNING:
#   1. R2_BUCKET below is set to a PLACEHOLDER. Update it to your real bucket
#      name (the credentials shared did not include the bucket name).
#   2. Credentials below are the PLACEHOLDER values from the conversation.
#      Swap them for your real values before running.
#   3. DRY_RUN defaults to 1. First run will list what WOULD be uploaded
#      without sending anything. Re-run with DRY_RUN=0 to actually upload.
#
# USAGE:
#   chmod +x upload_to_r2.sh
#   ./upload_to_r2.sh                  # dry run (default)
#   DRY_RUN=0 ./upload_to_r2.sh        # actual upload
#   DRY_RUN=0 R2_BUCKET=my-bucket ./upload_to_r2.sh
# =============================================================================

set -euo pipefail

# ------- CONFIGURATION -------------------------------------------------------

# R2 credentials (PLACEHOLDERS — replace before running)
R2_ACCESS_KEY_ID="a7628beccef8c148667f7e59bfdd94a7"
R2_SECRET_ACCESS_KEY="cbdb0709d836d2cab538656f26a34d6e8c4cd16bdc6c6d093b57cf3c9db8325c"
R2_ENDPOINT="https://c08ed3169672bf42db9b0b3ff144f970.r2.cloudflarestorage.com"

# Bucket name (NOT in the credentials I was given — set this explicitly).
# Override at the command line with: R2_BUCKET=real-bucket-name ./upload_to_r2.sh
R2_BUCKET="${R2_BUCKET:-cot-pod-sync}"

# Local paths
REPO_ROOT="${REPO_ROOT:-/workspace/narcbench}"

# Remote prefix — top-level "folder" in the bucket where this upload lives.
# Using a content-descriptive name; you can date-stamp it if you prefer.
REMOTE_PREFIX="${REMOTE_PREFIX:-day17_phase1_complete}"

# Dry-run mode: 1 = list only (default), 0 = actually upload.
DRY_RUN="${DRY_RUN:-1}"

# rclone remote name for the R2 config block. Won't collide with existing
# config because we check before writing.
REMOTE_NAME="r2_narcbench"

# ------- HELPERS -------------------------------------------------------------

log() { printf '[%s] %s\n' "$(date +%H:%M:%S)" "$*" >&2; }
die() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }

# ------- STEP 1: PRECHECKS ---------------------------------------------------

log "Repo root: $REPO_ROOT"
log "Bucket:    $R2_BUCKET"
log "Prefix:    $REMOTE_PREFIX"
log "Dry-run:   $DRY_RUN"
log ""

[[ -d "$REPO_ROOT" ]] || die "REPO_ROOT does not exist: $REPO_ROOT"
[[ -d "$REPO_ROOT/data/raw/stego" ]] || die "v4 batch missing: $REPO_ROOT/data/raw/stego"
[[ -d "$REPO_ROOT/data/processed/leakage_screen" ]] || die "leakage screen missing"

# ------- STEP 2: INSTALL RCLONE IF MISSING -----------------------------------

if ! command -v rclone >/dev/null 2>&1; then
  log "rclone not found — installing..."
  curl -fsSL https://rclone.org/install.sh | sudo bash >&2
fi

log "rclone version: $(rclone version | head -1)"

# ------- STEP 3: WRITE RCLONE CONFIG -----------------------------------------

RCLONE_CONF="${HOME}/.config/rclone/rclone.conf"
mkdir -p "$(dirname "$RCLONE_CONF")"
touch "$RCLONE_CONF"
chmod 600 "$RCLONE_CONF"

if grep -q "^\[${REMOTE_NAME}\]" "$RCLONE_CONF"; then
  log "rclone remote '$REMOTE_NAME' already configured in $RCLONE_CONF"
  log "  (skipping write — delete the block and re-run if you want to rotate credentials)"
else
  log "Writing rclone remote '$REMOTE_NAME' to $RCLONE_CONF"
  cat >> "$RCLONE_CONF" <<EOF

[${REMOTE_NAME}]
type = s3
provider = Cloudflare
access_key_id = ${R2_ACCESS_KEY_ID}
secret_access_key = ${R2_SECRET_ACCESS_KEY}
endpoint = ${R2_ENDPOINT}
acl = private
no_check_bucket = true
EOF
fi

# ------- STEP 4: VERIFY CONNECTIVITY -----------------------------------------

log "Verifying connectivity (listing bucket root)..."
if ! rclone lsd "${REMOTE_NAME}:${R2_BUCKET}" 2>&1; then
  die "Cannot reach bucket. Check (a) credentials, (b) bucket name '$R2_BUCKET', (c) network."
fi

# ------- STEP 5: BUILD MANIFEST WITH CHECKSUMS -------------------------------
# The manifest is the reproducibility document. It captures exactly which file
# contents were uploaded, so we can later verify "the 100% result came from
# these specific bytes". This is the artifact a reviewer cares about.

MANIFEST_FILE="${REPO_ROOT}/upload_manifest_${REMOTE_PREFIX}.txt"
log "Building manifest at $MANIFEST_FILE"

{
  printf '# Upload manifest\n'
  printf '# Generated: %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  printf '# Host: %s\n' "$(hostname)"
  printf '# Repo: %s\n' "$REPO_ROOT"
  if (cd "$REPO_ROOT" && git rev-parse HEAD >/dev/null 2>&1); then
    printf '# Git HEAD: %s\n' "$(cd "$REPO_ROOT" && git rev-parse HEAD)"
    printf '# Git status: %d uncommitted file(s)\n' \
      "$(cd "$REPO_ROOT" && git status --porcelain | wc -l)"
  fi
  printf '# Bucket: %s\n' "$R2_BUCKET"
  printf '# Prefix: %s\n' "$REMOTE_PREFIX"
  printf '#\n'
  printf '# Columns: sha256  size_bytes  local_path\n'
  printf '\n'

  # Walk each upload root and emit one line per file.
  SOURCES=(
    "$REPO_ROOT/data/raw/stego"
    "$REPO_ROOT/data/processed/leakage_screen"
    "$REPO_ROOT/docs/predictions_v4.md"
    "$REPO_ROOT/docs/framing_memo_phase2.md"
  )

  for src in "${SOURCES[@]}"; do
    if [[ ! -e "$src" ]]; then
      printf '# SKIPPED (not found): %s\n' "$src"
      continue
    fi
    if [[ -d "$src" ]]; then
      find "$src" -type f -print0 \
        | sort -z \
        | while IFS= read -r -d '' f; do
            printf '%s  %d  %s\n' \
              "$(sha256sum "$f" | awk '{print $1}')" \
              "$(stat -c %s "$f")" \
              "$f"
          done
    else
      printf '%s  %d  %s\n' \
        "$(sha256sum "$src" | awk '{print $1}')" \
        "$(stat -c %s "$src")" \
        "$src"
    fi
  done
} > "$MANIFEST_FILE"

n_files=$(grep -cv '^#' "$MANIFEST_FILE" 2>/dev/null || echo 0)
log "Manifest covers $n_files file(s); see $MANIFEST_FILE"

# ------- STEP 6: UPLOAD ------------------------------------------------------

RCLONE_FLAGS=(
  --progress
  --transfers 8
  --checkers 16
  --s3-chunk-size 16M
  --s3-upload-concurrency 4
  --stats 10s
  --stats-one-line
  --log-level INFO
)

if [[ "$DRY_RUN" == "1" ]]; then
  RCLONE_FLAGS+=(--dry-run)
  log "============================================================"
  log "DRY RUN MODE — nothing will actually upload."
  log "Re-run with DRY_RUN=0 ./upload_to_r2.sh to do the real upload."
  log "============================================================"
fi

upload_dir() {
  local src="$1" dest="$2"
  if [[ ! -d "$src" ]]; then
    log "SKIP (directory missing): $src"
    return
  fi
  log ">>> $src  -->  ${REMOTE_NAME}:${R2_BUCKET}/${dest}"
  rclone copy "$src" "${REMOTE_NAME}:${R2_BUCKET}/${dest}" "${RCLONE_FLAGS[@]}"
}

upload_file() {
  local src="$1" dest="$2"
  if [[ ! -f "$src" ]]; then
    log "SKIP (file missing): $src"
    return
  fi
  log ">>> $src  -->  ${REMOTE_NAME}:${R2_BUCKET}/${dest}"
  rclone copyto "$src" "${REMOTE_NAME}:${R2_BUCKET}/${dest}" "${RCLONE_FLAGS[@]}"
}

# v4 clean batch — the headline data
upload_dir  "$REPO_ROOT/data/raw/stego" \
            "${REMOTE_PREFIX}/data/raw/stego_v4_clean"

# Judge pipeline outputs (think blocks, judge results, score summary, spot check)
upload_dir  "$REPO_ROOT/data/processed/leakage_screen" \
            "${REMOTE_PREFIX}/data/processed/leakage_screen"

# Pre-registration document (committed Day 16 before generation)
upload_file "$REPO_ROOT/docs/predictions_v4.md" \
            "${REMOTE_PREFIX}/docs/predictions_v4.md"

# Phase-2 framing memo (delivered Day 17)
upload_file "$REPO_ROOT/docs/framing_memo_phase2.md" \
            "${REMOTE_PREFIX}/docs/framing_memo_phase2.md"

# Manifest goes last so it captures the full intended set
upload_file "$MANIFEST_FILE" \
            "${REMOTE_PREFIX}/upload_manifest.txt"

# ------- STEP 7: VERIFY UPLOAD -----------------------------------------------

log ""
log "============================================================"
if [[ "$DRY_RUN" == "1" ]]; then
  log "Dry run complete. Inspect output above; re-run with DRY_RUN=0 to upload."
else
  log "Upload complete. Verifying remote contents:"
  rclone size "${REMOTE_NAME}:${R2_BUCKET}/${REMOTE_PREFIX}"
  log ""
  log "Top-level layout:"
  rclone lsd "${REMOTE_NAME}:${R2_BUCKET}/${REMOTE_PREFIX}" \
    --max-depth 3 2>/dev/null || \
    rclone ls "${REMOTE_NAME}:${R2_BUCKET}/${REMOTE_PREFIX}" | head -30
fi
log "============================================================"

# ------- DONE ----------------------------------------------------------------
# To later verify a single file matches what was uploaded:
#
#   rclone hashsum SHA256 \
#     ${REMOTE_NAME}:${R2_BUCKET}/${REMOTE_PREFIX}/path/to/file
#
# Compare against the corresponding line in upload_manifest_${REMOTE_PREFIX}.txt.
# =============================================================================